System.out.println("=== INNER JOIN ===");
printCounted(stmt.executeQuery("""
    SELECT u.name, o.id AS order_id, o.amount
    FROM users u
    INNER JOIN orders o ON o.user_id = u.id
    """));
// Zwraca TYLKO wiersze, ktore maja DOPASOWANIE PO OBU stronach.
// Uzytkownik bez zamowien i osierocone zamowienie (bez uzytkownika) - POMINIETE.

System.out.println("=== LEFT JOIN ===");
printCounted(stmt.executeQuery("""
    SELECT u.name, o.id AS order_id, o.amount
    FROM users u
    LEFT JOIN orders o ON o.user_id = u.id
    """));
// Zwraca WSZYSTKIE wiersze z LEWEJ tabeli (users), nawet bez dopasowania
// - wtedy kolumny z prawej tabeli maja wartosc NULL.

System.out.println("\n=== RIGHT JOIN ===");
printCounted(stmt.executeQuery("""
    SELECT u.name, o.id AS order_id, o.amount
    FROM users u
    RIGHT JOIN orders o ON o.user_id = u.id
    """));
// Lustrzane odbicie LEFT JOIN - wszystkie wiersze z PRAWEJ tabeli (orders).

System.out.println("=== FULL JOIN - emulacja przez UNION LEFT + RIGHT JOIN ===");
printCounted(stmt.executeQuery("""
    SELECT u.name, o.id AS order_id, o.amount
    FROM users u
    LEFT JOIN orders o ON o.user_id = u.id
    UNION
    SELECT u.name, o.id AS order_id, o.amount
    FROM users u
    RIGHT JOIN orders o ON o.user_id = u.id
    """));
// UNION (bez ALL) automatycznie usuwa zduplikowane, dopasowane pary.

System.out.println("\n=== CROSS JOIN (iloczyn kartezjanski, 3 x 4 = 12 wierszy) ===");
printCounted(stmt.executeQuery("SELECT u.name, o.id FROM users u CROSS JOIN orders o"));
// CROSS JOIN: KAZDY wiersz lewej tabeli polaczony z KAZDYM wierszem prawej,
// BEZ zadnego warunku dopasowania - liczba wierszy = iloczyn liczby wierszy.

System.out.println("=== SELF JOIN (pracownik -> jego manager) ===");
printCounted(stmt.executeQuery("""
    SELECT e.name AS pracownik, m.name AS manager
    FROM employees e
    LEFT JOIN employees m ON e.manager_id = m.id
    """));
// SELF JOIN to nie osobny typ JOIN-a (technicznie zwykly INNER/LEFT JOIN),
// tylko przypadek, gdy tabela odwoluje sie do SIEBIE SAMEJ. Zeby SQL wiedzial,
// o 'ktora kopie' tabeli chodzi, nadajemy jej DWA ROZNE ALIASY (e, m).
// LEFT JOIN, bo najwyzszy w hierarchii (CEO) nie ma managera (manager_id=NULL).
